package counter

import "testing"

func TestSanity(t *testing.T) {
	c := NewCounter()
	if c.Lines() != 0 || c.Letters() != 0 || c.Characters() != 0 {
		t.Fatal("fresh counter should be zero")
	}
	c.AddString("hello")
	check(t, c, 1, 5, 5)
	c.AddString(" world\n")
	check(t, c, 2, 10, 12)
	c.AddString("héllo\n")
	check(t, c, 3, 15, 18)
}

func check(t *testing.T, c Counter, lines, letters, chars int) {
	t.Helper()
	if c.Lines() != lines || c.Letters() != letters || c.Characters() != chars {
		t.Fatalf("got lines=%d letters=%d chars=%d, want %d/%d/%d",
			c.Lines(), c.Letters(), c.Characters(), lines, letters, chars)
	}
}
EOF
